cat > $D/ClaimStatus.java <<'EOF'
package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a DRAFT or
 * OPEN claim can be voided (VOID). SETTLED and VOID are final. Only OPEN and SETTLED claims count
 * toward any total.
 */
public enum ClaimStatus {
    DRAFT(null), OPEN("CLAIM_OPENED"), SETTLED("CLAIM_SETTLED"), VOID("CLAIM_VOIDED");

    private final String auditEvent;

    ClaimStatus(String auditEvent) {
        this.auditEvent = auditEvent;
    }

    /** The audit event written when a claim moves into this status. */
    public String auditEvent() {
        return auditEvent;
    }

    /** Whether a claim in this status may move to {@code next}. */
    public boolean canMoveTo(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
    }
}
EOF
cat > $D/InvalidClaimStatusException.java <<'EOF'
package net.officefloor.hq.app.claim;

/** A status change the claim's current status does not allow. */
public class InvalidClaimStatusException extends Exception {
    public InvalidClaimStatusException(ClaimStatus from, ClaimStatus to) {
        super("A " + from + " claim cannot become " + to);
    }
}
EOF
cat > $D/HandleInvalidClaimStatus.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidClaimStatus {
    public void handle(@Parameter InvalidClaimStatusException ex,
            ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
EOF
